import pandas as pd
import numpy as np

# Run the task_j logic to get the numbers for tau values 0.02 and 0.07
BASE_MISCLASS = 0.15
TAU_Z0_SWEEP = [0.01, 0.02, 0.03, 0.05, 0.07, 0.10, 0.15, 0.20]

df_all = pd.read_csv('results/exp002_bias_bound.csv')
df_z0 = df_all[df_all['z_value'] == 0].copy()

df_z0['pi_s'] = np.where(
    df_z0['subgroup'] == 'A',
    BASE_MISCLASS + df_z0['delta_misclass'] / 2.0,
    BASE_MISCLASS - df_z0['delta_misclass'] / 2.0
)
df_z0['bias_naive'] = df_z0['pi_s'] * df_z0['delta_cate']
df_z0['bias_global'] = df_z0['analytic_bias']

rows = []
for tau0 in TAU_Z0_SWEEP:
    for _, r in df_z0.iterrows():
        true_cate = tau0
        est_naive = tau0 + r['bias_naive']
        est_global = tau0 + r['bias_global']
        rev_global = (true_cate > 0 and est_global < 0) or (true_cate < 0 and est_global > 0)
        rows.append({
            'tau_z0': tau0,
            'reversal_global': rev_global,
            'est_global': est_global,
        })

df_sweep = pd.DataFrame(rows)

agg = df_sweep.groupby('tau_z0').agg(
    n_configs=('reversal_global', 'count'),
    n_rev_global=('reversal_global', 'sum'),
).reset_index()
agg['pct_rev_global'] = 100.0 * agg['n_rev_global'] / agg['n_configs']

# Most extreme est_global for sign reversals
for tau0 in TAU_Z0_SWEEP:
    sub = df_sweep[(df_sweep['tau_z0'] == tau0) & (df_sweep['reversal_global'])]
    if len(sub) > 0:
        most_neg = sub['est_global'].min()
        print(f'tau(0)={tau0:.2f}: reversals={int(agg[agg[\"tau_z0\"]==tau0][\"n_rev_global\"].iloc[0])}, pct={agg[agg[\"tau_z0\"]==tau0][\"pct_rev_global\"].iloc[0]:.1f}%, most_extreme_global_cate={most_neg:.6f}')
    else:
        print(f'tau(0)={tau0:.2f}: reversals=0, pct=0.0%')

# Max |bias_global| for z=0 (critical threshold)
max_abs_bias_z0 = df_z0['bias_global'].abs().max()
print(f'\nMax |bias_global| for Z=0 (critical threshold): {max_abs_bias_z0:.6f}')
print(f'n_z0 configs total: {len(df_z0)}')
