import pandas as pd
import numpy as np

BASE_MISCLASS = 0.15
df = pd.read_csv('results/exp002_bias_bound.csv')
print('Columns:', list(df.columns))
print('Shape:', df.shape)
print()
print('First 3 rows:')
print(df.head(3).to_string())
print()

# Reconstruct naive bias
pi_s = np.where(df.subgroup == 'A',
                BASE_MISCLASS + df.delta_misclass / 2,
                BASE_MISCLASS - df.delta_misclass / 2)

sign = np.where(df.z_value == 0, 1.0, -1.0)
df['bias_naive'] = sign * pi_s * df.delta_cate
df['bias_global'] = df.analytic_bias

# Exclude trivial
nontrivial = (df.bias_naive.abs() > 1e-15) | (df.bias_global.abs() > 1e-15)
df_nt = df[nontrivial].copy()

total = len(df_nt)
hurts = (df_nt.bias_global.abs() > df_nt.bias_naive.abs()).sum()
severe = (df_nt.bias_global.abs() > 2 * df_nt.bias_naive.abs()).sum()

safe = df_nt.bias_naive.abs() > 1e-15
ratios = df_nt.loc[safe, 'bias_global'].abs() / df_nt.loc[safe, 'bias_naive'].abs()
worst = ratios.max()

print(f'Total nontrivial: {total}')
print(f'Hurts: {hurts}')
print(f'Hurts pct: {100*hurts/total:.1f}%')
print(f'Severe: {severe}')
print(f'Worst ratio: {worst:.4f}')

# K=2 subset
k2_mask = df_nt.k_subgroups == 2 if 'k_subgroups' in df_nt.columns else None
if k2_mask is not None:
    k2 = df_nt[k2_mask]
    k2_total = len(k2)
    k2_hurts = (k2.bias_global.abs() > k2.bias_naive.abs()).sum()
