    k2_ratios = k2.loc[k2_safe, 'bias_global'].abs() / k2.loc[k2_safe, 'bias_naive'].abs()
    k2_worst = k2_ratios.max()
    print(f'\\nK=2 total nontrivial: {k2_total}')
    print(f'K=2 hurts: {k2_hurts}')
