        kappa_pass.add((row['llm'], row['dataset'], row['K'], row['subgroup']))
print(f'Rows passing kappa: {len(kappa_pass)}')

# Group: how many combos have ALL subgroups pass kappa?
from collections import defaultdict
combo_pass = defaultdict(list)
for row in rows:
