pred = valid['analytic_bias'].values
obs = valid['mc_bias'].values
ss_res = np.sum((obs - pred) ** 2)
ss_tot = np.sum((obs - np.mean(obs)) ** 2)
r2 = 1 - ss_res / ss_tot
