BASE_MISCLASS = 0.15
TAU_Z0 = 0.03

df['pi_s'] = np.where(
    df['subgroup'] == 'A',
    BASE_MISCLASS + df['delta_misclass'] / 2.0,
    BASE_MISCLASS - df['delta_misclass'] / 2.0
